    items.push_back({c0, d0, n / c0}); // plain buns: max possible
    for (int i = 0; i < m; i++) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        int max_num = min(a / b, n / c);
        items.push_back({c, d, max_num});
    }
    vector<int> dp(n + 1, 0);
    for (auto& item : items) {
        int c = item[0], d = item[1], max_num = item[2];
        for (int j = n; j >= 0; j--) {
            for (int k = 1; k <= max_num && k * c <= j; k++) {
                dp[j] = max(dp[j], dp[j - k * c] + k * d);
            }
        }
    }
    cout << dp[n] << endl;
    return 0;
}
